/// <reference lib="webworker" />

import { cleanupOutdatedCaches, createHandlerBoundToURL, precacheAndRoute } from 'workbox-precaching'
import { NavigationRoute, registerRoute } from 'workbox-routing'
import { NetworkFirst } from 'workbox-strategies'

declare const self: ServiceWorkerGlobalScope

// Precache static assets (generated by vite-plugin-pwa)
cleanupOutdatedCaches()
precacheAndRoute(self.__WB_MANIFEST || [])

// App shell: every page load is served from the precached index.html, so an
// installed app opens instantly and offline. The shell and its JS/CSS update together.
registerRoute(new NavigationRoute(createHandlerBoundToURL('index.html')))

// Network-first for API calls
registerRoute(/^https:\/\/api\//, new NetworkFirst({ cacheName: 'api-cache' }))

// Handle push events
self.addEventListener('push', (event) => {
  if (!event.data) return

  try {
    const payload = event.data.json() as {
      alertId?: string
      title?: string
      body?: string
      icon?: string
      badge?: string
      url?: string
      unreadCount?: number
    }

    const title = payload.title || 'SiteSeal Inventory'
    const options: NotificationOptions = {
      body: payload.body || '',
      icon: payload.icon || '/favicon.svg',
      badge: payload.badge || '/pwa-64x64.png',
      tag: payload.alertId || 'siteseal-notification',
      data: { url: payload.url || '/' },
      requireInteraction: false,
    }

    event.waitUntil(self.registration.showNotification(title, options))

    // Update app badge if unread count provided
    if (typeof payload.unreadCount === 'number' && 'setAppBadge' in self.navigator) {
      event.waitUntil(
        (self.navigator as any).setAppBadge(payload.unreadCount).catch(() => {
          // Silently ignore badge errors
        }),
      )
    }
  } catch (error) {
    console.error('Push event parsing failed:', error)
  }
})

// Handle notification clicks
self.addEventListener('notificationclick', (event) => {
  event.notification.close()

  const url = event.notification.data?.url || '/'

  // Validate URL is same-origin
  if (!url.startsWith('/') && !url.startsWith(self.location.origin)) {
    return
  }

  event.waitUntil(
    (self as any).clients
      .matchAll({ type: 'window', includeUncontrolled: true })
      .then((clients: WindowClient[]) => {
        // Try to find an existing window
        for (const client of clients) {
          if (client.url === new URL(url, self.location.origin).href && 'focus' in client) {
            return (client as any).focus()
          }
        }
        // Otherwise open a new window
        if ('openWindow' in self.clients) {
          return (self.clients as any).openWindow(url)
        }
      }),
  )
})

// Message event for updating app badge from React
self.addEventListener('message', (event) => {
  if (event.data?.type === 'SKIP_WAITING') {
    void self.skipWaiting()
    return
  }
  if (event.data?.type === 'UPDATE_BADGE' && 'setAppBadge' in self.navigator) {
    const count = event.data.count as number
    if (count > 0) {
      (self.navigator as any).setAppBadge(count).catch(() => {
        // Silently ignore badge errors
      })
    } else {
      (self.navigator as any).clearAppBadge?.().catch(() => {
        // Silently ignore badge errors
      })
    }
  }
})

export {}
